// Block (composition) — a responsive band of labeled key statistics.
// Grid owns responsive columns; Stack owns each statistic's arrangement and this Block owns its content structure.
import type { Ref } from "react";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./StatsBand.css";

export interface StatsBandProps {
  stats: {
    label: string;
    value: string;
    description?: string;
  }[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function StatsBand({
  stats,
  columns = { small: 2, medium: 4 },
  className,
  ref,
}: StatsBandProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Key statistics"
      columns={columns}
      gap="large"
      className={className ? `sd-statsband ${className}` : "sd-statsband"}
    >
      {stats.map((stat, index) => (
        <Stack key={`${stat.label}-${index}`} align="center" gap="2x-small" className="sd-statsband__stat">
          <strong className="sd-statsband__value sd-type-display-medium">{stat.value}</strong>
          <span className="sd-statsband__label sd-type-label-medium">{stat.label}</span>
          {stat.description && (
            <span className="sd-statsband__description sd-type-caption-medium">
              {stat.description}
            </span>
          )}
        </Stack>
      ))}
    </Grid>
  );
}

.sd-statsband {
  width: 100%;
  text-align: center;
}

.sd-statsband__value,
.sd-statsband__label,
.sd-statsband__description {
  margin: 0;
}

.sd-statsband__description {
  color: var(--sd-color-text-muted);
}

.sd-statsband__value {
  /* A value that changes in place (a count, a percentage) keeps its width, so it does not jitter as
     its digits change. */
  font-variant-numeric: tabular-nums;
}
